class Solution { const int LARGE=2'000'000'000;long long shortest(int n,vector<vector<int>>& edges,int source,int destination){vector<vector<pair<int,int>>> graph(n);for(auto& edge:edges)if(edge[2]>=0){graph[edge[0]].push_back({edge[1],edge[2]});graph[edge[1]].push_back({edge[0],edge[2]});}vector<long long> distance(n,LLONG_MAX);distance[source]=0;priority_queue<pair<long long,int>,vector<pair<long long,int>>,greater<pair<long long,int>>> queue;queue.push({0,source});while(!queue.empty()){auto [cost,node]=queue.top();queue.pop();if(cost!=distance[node])continue;if(node==destination)return cost;for(auto [next,weight]:graph[node])if(cost+weight<distance[next]){distance[next]=cost+weight;queue.push({distance[next],next});}}return LLONG_MAX;}public:vector<vector<int>> modifiedGraphEdges(int n,vector<vector<int>>& edges,int source,int destination,int target){long long fixed=shortest(n,edges,source,destination);if(fixed<target)return{};bool matched=fixed==target;for(auto& edge:edges)if(edge[2]==-1){if(matched)edge[2]=LARGE;else{edge[2]=1;long long distance=shortest(n,edges,source,destination);if(distance<=target){edge[2]+=target-distance;matched=true;}}}return matched?edges:vector<vector<int>>{};} };
